LESSONS.forEach(l=>{l.week=1;l.source=DATA.bioSource});
window.WEEK_ADDITIONS=[{"id": "classification", "week": 1, "title": "人体在生物分类中的位置", "en": "Human Classification", "time": "18–25 分钟", "pages": "9–13", "goals": ["理解生物分类层级", "将人体特征与共同祖先联系起来"], "englishGoals": ["Follow the taxonomic hierarchy", "Connect human features with shared ancestry"], "html": "<h2>人类属于一层层嵌套的分类</h2><p>分类根据共同特征和进化关系组织生物。讲义顺序为<strong>动物界 → 脊索动物门 → 脊椎动物亚门 → 哺乳纲 → 灵长目 → 人科 → 人属 → 智人种</strong>。Homo 是属名，Homo sapiens 是种名。</p><h3>脊索动物特征可以在发育阶段出现</h3><p>人类胚胎有脊索、背侧中空神经管、咽部结构，以及延伸至肛门之后的尾。发育中它们发生变化：神经管形成脑和脊髓，尾骨是尾的遗留结构。人类咽部结构不会形成具有鱼鳃功能的器官。</p><p>脊椎动物有内骨骼、脊柱及保护脑的颅骨。哺乳动物特征包括乳腺、毛发、通过代谢产生体热的内温性、不同类型牙齿的异型齿性、单一的下颌骨及三块中耳听小骨。</p><p>讲义强调灵长类的前向眼睛、立体视觉、扁平指甲和对握拇指；人类还以双足行走、复杂语言和抽象思维为特征。判断物种不能只凭单个特征。</p><div class=\"teacher\">把分类想成文件夹套文件夹：人类属于哺乳动物，同时也属于脊椎动物和脊索动物。练习依次说出层级，再给每个层级配一个特征。</div>", "englishHtml": "<h2>Humans belong to nested groups</h2><p>Classification groups organisms by shared characteristics and evolutionary relationships. The lecture sequence is <strong>Animalia → Chordata → Vertebrata → Mammalia → Primates → Hominidae → Homo → Homo sapiens</strong>: kingdom, phylum, subphylum, class, order, family, genus and species. Homo is the genus; Homo sapiens is the species.</p><h3>Chordate features appear during development</h3><p>The human embryo has a notochord, dorsal hollow nerve cord, pharyngeal structures and a tail extending beyond the anus. These features are transformed during development: the nerve cord develops into the brain and spinal cord, and the coccyx is a tail remnant. Human pharyngeal structures do not form functioning fish gills.</p><p>Vertebrates have an internal skeleton, vertebral column and a protective cranium. Mammalian characteristics include mammary glands, hair, metabolic heat production (endothermy), different tooth types (heterodonty), a single lower jawbone and three middle-ear bones.</p><p>Primate features highlighted in the slides include forward-facing eyes, stereoscopic vision, flat nails and opposable thumbs. The lecture associates humans with bipedalism, complex language and abstract thinking. Do not use a single feature alone to decide a species.</p><div class=\"teacher\">Think of folders inside folders: being a mammal does not stop a human from also being a vertebrate and a chordate. Practise naming each level, then give a feature associated with it.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061514", "questions": [{"id": "classification-1", "text": "Homo sapiens 中哪部分是属名？", "options": ["单独的 sapiens", "Mammalia", "Homo"], "answer": 2, "explain": "Homo 是属名，两词合起来的 Homo sapiens 是种名。"}, {"id": "classification-2", "text": "哪项特征最能支持归为哺乳动物？", "options": ["仅有脊柱", "细胞膜", "乳腺"], "answer": 2, "explain": "乳腺是哺乳动物特征；脊柱也见于其他脊椎动物。"}]}, {"id": "variation", "week": 1, "title": "正常差异与参考人体", "en": "Variation & Reference Models", "time": "18–25 分钟", "pages": "14–15", "goals": ["区分差异与疾病", "正确理解参考模型"], "englishGoals": ["Separate variation from disease", "Interpret a reference model"], "html": "<h2>教材中的人体是参照，不是每个人的完整复制</h2><p>解剖结构和生理功能都存在个体差异。<strong>正常变异</strong>可以与健康相容；<strong>病理变异</strong>与疾病有关。仅仅偏离平均值不足以判断疾病。</p><p>讲义的历史参考男性模型设定为健康、22岁、70 kg、环境20°C、轻体力活动及每天2,800 kcal；参考女性使用58 kg和每天2,000 kcal。这些是讲义模型的条件，不是你的饮食目标，也不是健康的统一标准。</p><div class=\"teacher\">工程模型让我们在明确的假设下比较计算。器械用于真实人体时，体型、解剖结构和生理差异都可能影响设计。先问：模型采用了哪些假设？</div><div class=\"callout\">请用自己的话解释：“不同于参考值”与“患有疾病”是两种不同判断。</div>", "englishHtml": "<h2>A textbook body is a reference, not every individual</h2><p>Anatomy and physiology vary among individuals. <strong>Normal variation</strong> is compatible with health; <strong>pathological variation</strong> is associated with disease. A difference from an average is not enough to identify pathology.</p><p>The slides describe a historical reference man: healthy, age 22, mass 70 kg, ambient temperature 20°C, light physical activity and 2,800 kcal/day. Their reference woman uses 58 kg and 2,000 kcal/day. These are assumptions of the lecture’s model, not personal nutrition targets or universal definitions of health.</p><div class=\"teacher\">In engineering, a model lets us compare calculations under stated assumptions. When a device is designed for real people, body size, anatomy and physiological variability may matter. First ask which assumptions are being used.</div><div class=\"callout\">Explain the distinction in your own words: “different from a reference value” and “diseased” are different claims.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061514", "questions": [{"id": "variation-1", "text": "某人的体重与参考模型不同，仅凭这一点可以得出什么？", "options": ["参考模型不能使用", "一定患病", "此人与模型不同，尚不能判断患病"], "answer": 2, "explain": "参考模型用于比较，差异本身不能确立病理状态。"}, {"id": "variation-2", "text": "为什么需要写出参考模型的活动水平和环境温度？", "options": ["它们说明解读结果所用的假设", "这些条件必须适用于所有人", "它们确定人的属名"], "answer": 0, "explain": "模型结果依赖假设，这些条件帮助我们正确解读模型。"}]}, {"id": "regions", "week": 1, "title": "身体方向、区域与腹部定位", "en": "Body Regions & Abdominal Mapping", "time": "18–25 分钟", "pages": "21–27", "goals": ["使用区域与方向术语", "定位腹部四象限和九区"], "englishGoals": ["Use regional and directional terminology", "Locate abdominal quadrants and nine regions"], "html": "<h2>先描述关系，再记名称</h2><p>在直立人体中，anterior/ventral 指前侧，posterior/dorsal 指后侧；superior 指上方，inferior 指下方；superficial 指浅表，deep 指深部。Cephalic 指向头端，caudal 指向尾端；描述头部相关结构时，rostral 指向额部或鼻端。</p><p>轴部区域包括头、颈和躯干；附肢区域包括四肢。Brachial 是上臂，antebrachial 是前臂，carpal 是腕部，palmar 是手掌；femoral 是大腿，crural 是小腿，tarsal 是踝部，plantar 是足底。解剖学的“arm”和“leg”比日常语言的范围更窄。</p><p>图中其他名称：axillary 腋部、cubital 肘部、cephalic 头部、cervical 颈部、thoracic 胸部、sternal 胸骨部、umbilical 脐部、inguinal 腹股沟、patellar 膝前、popliteal 膝后、nuchal 颈后、scapular 肩胛部、vertebral 脊柱部、lumbar 腰部，以及 sacral 骶部和 gluteal 臀部。</p><h3>四象限与九区是两套定位地图</h3><p>通过脐部的水平线与垂直中线划分右上、左上、右下、左下四象限。左右指被描述者自己的左右，不是观察者的左右。</p><p>九区使用两条锁骨中线，以及肋下线和髂结节间线。上排：右季肋区—上腹区—左季肋区；中排：右腰区—脐区—左腰区；下排：右腹股沟/髂区—下腹/耻骨区—左腹股沟/髂区。</p><div class=\"teacher\">画一个3×3网格，以人体自身视角标注，再解释踝部为什么在膝后区域的远端。用位置关系推理，不靠单词拼写猜测。</div>", "englishHtml": "<h2>Describe a relationship before memorising names</h2><p>In an upright human, anterior/ventral means towards the front; posterior/dorsal means towards the back. Superior means above; inferior below. Superficial is nearer the body surface; deep farther from it. Cephalic is towards the head, caudal towards the tail end, and rostral towards the forehead or nose in relevant head descriptions.</p><p>The axial region includes head, neck and trunk; the appendicular region includes limbs. Brachial = upper arm; antebrachial = forearm; carpal = wrist; palmar = palm. Femoral = thigh; crural = lower leg; tarsal = ankle; plantar = sole. In anatomical naming, “arm” and “leg” are narrower terms than in everyday speech.</p><p>Other labels in the diagrams: axillary (armpit), cubital (elbow), cephalic (head), cervical (neck), thoracic (chest), sternal (breastbone), umbilical (navel), inguinal (groin), patellar (front of knee), popliteal (back of knee), nuchal (back of neck), scapular (shoulder-blade region), vertebral (spinal region), lumbar (lower back), sacral and gluteal (buttock) regions.</p><h3>Four quadrants and nine regions are different maps</h3><p>A vertical midline and a horizontal line through the umbilicus define right upper, left upper, right lower and left lower quadrants. Right and left are the subject’s sides, not the viewer’s.</p><p>The nine-region map uses two midclavicular lines and horizontal subcostal and intertubercular lines. Top row: right hypochondriac – epigastric – left hypochondriac. Middle: right lumbar – umbilical – left lumbar. Bottom: right inguinal/iliac – hypogastric/pubic – left inguinal/iliac.</p><div class=\"teacher\">Draw a 3×3 grid and label it from the subject’s perspective. Then explain why the ankle is distal to the back of the knee. Use position rather than guessing from the spelling.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061514", "questions": [{"id": "regions-1", "text": "膝后区域叫什么？", "options": ["Patellar 膝前", "Popliteal 膝后", "Carpal 腕部"], "answer": 1, "explain": "Popliteal 指膝后；patellar 指膝前。"}, {"id": "regions-2", "text": "腹部九区中正中间一格是什么？", "options": ["脐区", "下腹区", "上腹区"], "answer": 0, "explain": "脐区位于中排中列。"}]}, {"id": "cavities", "week": 1, "title": "体腔、浆膜与腹膜位置", "en": "Cavities & Serous Membranes", "time": "18–25 分钟", "pages": "28–31", "goals": ["建立主要体腔地图", "区分脏层和壁层"], "englishGoals": ["Map major cavities", "Distinguish visceral from parietal layers"], "html": "<h2>先理解器官周围的空间</h2><p>颅腔容纳脑，椎管容纳脊髓。胸腔位于膈肌上方，腹盆腔位于其下方。胸部包括肺周围的胸膜腔及纵隔；心脏及其心包位于纵隔。</p><p>浆膜具有相关的两层：<strong>壁层 parietal</strong>衬在腔壁，<strong>脏层 visceral</strong>覆盖器官表面。两层之间的潜在空间含少量润滑液，减少运动时的摩擦；器官本身并不是漂浮在这层薄薄的浆膜腔里。</p><p>胸膜 pleura 与肺有关，心包 pericardium 与心脏有关，腹膜 peritoneum 与腹盆部结构有关。脑膜 meninges 包围脑和脊髓，不应归为胸膜或腹膜。</p><div class=\"teacher\">想象把拳头压入一个未破裂的充气袋：贴着拳头的一层类似脏层，外面的一层类似壁层。这个类比用于区分两层，真实浆膜腔通常只有薄层液体。</div><p>腹膜内器官的大部分表面被脏层腹膜覆盖，常通过肠系膜与体壁联系。肾等腹膜后结构位于壁层腹膜后方。位于腹部不意味着一定属于腹膜内器官。</p>", "englishHtml": "<h2>Start with the spaces around organs</h2><p>The cranial cavity contains the brain; the vertebral canal contains the spinal cord. The thoracic cavity is above the diaphragm; the abdominopelvic cavity is below it. The thorax includes pleural spaces around the lungs and the mediastinum, which contains the heart and its pericardial enclosure.</p><p>Serous membranes have two associated layers: the <strong>parietal</strong> layer lines the cavity wall, and the <strong>visceral</strong> layer covers the organ. A thin film of lubricating fluid in the potential space between them reduces friction during movement. The organ itself is not floating inside the thin serous space.</p><p>Pleura is associated with lungs; pericardium with the heart; peritoneum with abdominal and pelvic structures. Meninges surround the brain and spinal cord and should not be treated as pleura or peritoneum.</p><div class=\"teacher\">Imagine pushing a fist into an inflated bag without breaking it: the layer touching the fist resembles a visceral layer, and the outer layer resembles a parietal layer. The analogy helps distinguish layers, but real cavities contain only a thin fluid film.</div><p>Intraperitoneal organs are largely covered by visceral peritoneum and often supported by a mesentery. Retroperitoneal structures, such as the kidneys, lie behind the parietal peritoneum. Being in the abdominal region does not automatically mean being intraperitoneal.</p>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061514", "questions": [{"id": "cavities-1", "text": "直接覆盖器官表面的浆膜层是哪层？", "options": ["脏层", "都不是", "壁层"], "answer": 0, "explain": "脏层覆盖器官，壁层衬在腔壁。"}, {"id": "cavities-2", "text": "肾位于壁层腹膜后方，应归为什么？", "options": ["胸膜腔内", "腹膜内", "腹膜后"], "answer": 2, "explain": "腹膜后指位于壁层腹膜后方，仅有腹部位置不能判定为腹膜内。"}]}, {"id": "systems", "week": 1, "title": "人体系统如何协作", "en": "Body Systems Working Together", "time": "18–25 分钟", "pages": "32", "goals": ["连接器官与系统功能", "解释系统如何共同维持稳态"], "englishGoals": ["Connect organs with system functions", "Explain cooperation in homeostasis"], "html": "<h2>通过功能组织器官系统</h2><p>被皮系统：皮肤及附属结构形成屏障并帮助调温；骨骼系统：骨提供支撑和保护；肌肉系统：产生运动和热；神经系统：脑、脊髓与神经进行快速信号传递；内分泌系统：腺体释放激素进行调节。</p><p>心血管系统：心脏和血管输送血液；淋巴/免疫系统：回流组织液并支持防御；呼吸系统：气道和肺进行气体交换；消化系统：处理食物并吸收营养；泌尿系统：肾和尿路调节体液组成并排出废物；生殖系统：产生配子并支持繁殖，女性相关结构还可支持发育和哺乳。</p><div class=\"teacher\">运动时肌肉需要更多能量，呼吸与心血管系统帮助供应氧，神经与内分泌信号协调反应，皮肤帮助散热。同一活动可能需要多个系统协作。</div><div class=\"callout\">一个器官可能承担多种作用。应按题目所问功能判断，不能假定一个器官只有唯一系统标签。</div>", "englishHtml": "<h2>Use function to organise the body systems</h2><p>Integumentary: skin and associated structures provide a barrier and assist temperature regulation. Skeletal: bones support and protect. Muscular: muscles generate movement and heat. Nervous: brain, spinal cord and nerves provide rapid signalling. Endocrine: glands release hormones for regulation.</p><p>Cardiovascular: heart and vessels transport blood. Lymphatic/immune: return interstitial fluid and support defence. Respiratory: airways and lungs exchange gases. Digestive: process food and absorb nutrients. Urinary: kidneys and urinary tract regulate fluid composition and remove wastes. Reproductive: reproductive organs produce gametes and support reproduction; female structures can also support development and lactation.</p><div class=\"teacher\">During exercise, muscles use more energy; respiratory and cardiovascular systems help supply oxygen; nervous and endocrine signals coordinate responses; skin contributes to heat loss. One event can involve several systems.</div><div class=\"callout\">An organ can contribute to more than one role. Classify it by the function relevant to the question rather than assuming one exclusive label.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061514", "questions": [{"id": "systems-1", "text": "哪个系统最直接将含氧血液送到组织？", "options": ["生殖系统", "心血管系统", "被皮系统"], "answer": 1, "explain": "心脏和血管运输血液；呼吸系统进行气体交换，但不是全身血液循环的直接承担者。"}, {"id": "systems-2", "text": "运动时通气和心率同时增加，最适合说明什么？", "options": ["系统完全独立", "多个系统协作满足变化的需求", "只有骨骼发生变化"], "answer": 1, "explain": "呼吸与心血管变化在调节下共同满足肌肉代谢需求。"}]}, {"id": "molecule-detail", "week": 1, "title": "分子结构：从连接到折叠", "en": "Bonds, Lipid Roles & Protein Folding", "time": "18–25 分钟", "pages": "46–59", "goals": ["解释生物分子单元的连接和拆分", "连接蛋白结构层级与功能"], "englishGoals": ["Explain joining and splitting biological units", "Relate protein structure levels to function"], "html": "<h2>细小的结构差别会改变生物行为</h2><p>葡萄糖、果糖和半乳糖都是单糖。核糖和脱氧核糖为五碳糖，葡萄糖为六碳糖。(CH₂O)n 是许多糖类的常见模式，不是所有糖类的严格定义。α与β形式的区别位于异头碳处的基团方向。</p><p>糖苷键连接糖单元。缩合/脱水连接会释放水，水解利用水拆开键。蔗糖由葡萄糖和果糖组成，乳糖由半乳糖和葡萄糖组成，麦芽糖由两个葡萄糖组成。糖原是动物储存葡萄糖的形式，淀粉是植物的储存形式，纤维素支持植物结构并提供膳食纤维。</p><p>糖类还参与构成糖蛋白、糖脂和蛋白聚糖，与细胞表面、识别、黏附或细胞外支撑有关。脂质通常比糖类含较低比例的氧，但单凭组成比例不是完整分类标准。</p><p>饱和脂肪酸链没有碳碳双键，不饱和链有一个或多个。甘油三酯储存能量并帮助保温、缓冲；磷脂构成膜；胆固醇参与膜结构并作为类固醇前体；前列腺素等类二十烷酸作局部信号；胆汁酸帮助脂肪消化与吸收。</p><h3>蛋白质的四级结构</h3><p>一级结构是由肽键连接的氨基酸序列；二级结构包括由骨架氢键稳定的局部α螺旋和β折叠；三级结构是一条多肽的三维折叠；四级结构是多条多肽亚基的组装，血红蛋白就是例子。并非所有蛋白都有四级结构。</p><div class=\"teacher\">珠子序列、局部卷曲、整条链折叠以及多条链组装代表不同层级。序列变化可能影响折叠，继而影响功能。理解“序列”和“形状”的区别，比只记四个数字更有用。</div>", "englishHtml": "<h2>Small differences in structure change biological behaviour</h2><p>Glucose, fructose and galactose are monosaccharides. Ribose and deoxyribose are five-carbon sugars; glucose is a six-carbon sugar. The formula (CH₂O)n is a useful pattern for many carbohydrates, not a definition valid for every carbohydrate. α and β forms differ in the orientation at the anomeric carbon.</p><p>A glycosidic bond joins sugar units. Condensation/dehydration joining releases water; hydrolysis uses water to split a bond. Sucrose contains glucose and fructose; lactose contains galactose and glucose; maltose contains two glucose units. Glycogen stores glucose in animals; starch stores glucose in plants; cellulose supports plant structure and contributes dietary fibre.</p><p>Carbohydrates also participate in glycoproteins, glycolipids and proteoglycans involved in cell surfaces, recognition, adhesion or extracellular support. Lipids often contain proportionally less oxygen than carbohydrates; that compositional pattern alone is not a complete classification rule.</p><p>A saturated fatty-acid chain has no carbon–carbon double bonds; an unsaturated chain has one or more. Triglycerides store energy and help insulation and cushioning. Phospholipids form membranes; cholesterol contributes to membranes and is a steroid precursor; eicosanoids such as prostaglandins act as local chemical signals; bile acids assist fat digestion and absorption.</p><h3>Four levels of protein structure</h3><p>Primary structure is amino-acid sequence linked by peptide bonds. Secondary structure includes local α-helices and β-sheets stabilised by backbone hydrogen bonding. Tertiary structure is the three-dimensional folding of one polypeptide. Quaternary structure is the association of multiple polypeptide subunits; haemoglobin is an example. Not every protein has quaternary structure.</p><div class=\"teacher\">A bead sequence, local coils, a folded chain and several assembled chains represent different levels. Changing sequence can affect folding and therefore function. Distinguish sequence from shape rather than memorising four numbers.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061514", "questions": [{"id": "molecule-detail-1", "text": "利用水拆开糖苷键的过程叫什么？", "options": ["水解", "脱水合成", "翻译"], "answer": 0, "explain": "水解在断键过程中利用水，脱水连接释放水。"}, {"id": "molecule-detail-2", "text": "几条已折叠多肽亚基组装成蛋白，描述的是哪级结构？", "options": ["二级", "四级", "一级"], "answer": 1, "explain": "四级结构涉及多个多肽亚基；三级结构涉及一条链的整体折叠。"}]}, {"id": "cell-size", "week": 2, "title": "细胞是什么：形状、大小与组织", "en": "Cells, Size & Tissues", "time": "18–25 分钟", "pages": "3–9", "goals": ["将细胞形状与功能联系起来", "计算表面积体积比"], "englishGoals": ["Connect cell shape to function", "Calculate surface-area-to-volume ratio"], "html": "<h2>细胞是生命单位，不只是化学物质的袋子</h2><p>细胞是生物的基本单位，并维持有组织的内部条件。新细胞来自已有细胞；干细胞可产生特化细胞类型，但不能将讲义表述理解成每个活细胞都直接来自干细胞。胡克观察软木小室后命名“cell”。</p><p>讲义给出的典型原核细胞为1–10 μm，真核细胞为10–100 μm；这是近似范围，不是普遍边界。1 μm = 0.001 mm；1 nm = 0.001 μm。</p><p>形状包括扁平、立方、柱状、多边形、星形、球形、盘形、梭形和纤维形。扁平可缩短部分运输距离，长突起可支持通信。形状有助于推测功能，但不能仅凭形状确定细胞身份。</p><h3>为什么细胞变大可能使交换更困难？</h3><p>边长为L的立方体，面积6L²、体积L³，因此面积/体积=6/L。L为1 μm时比值为6 μm⁻¹，L为2 μm时为3 μm⁻¹。边长翻倍，交换面积变成4倍，体积变成8倍。较小体积常有利于交换并缩短扩散距离。</p><p>四类基本组织组织特化细胞：上皮组织负责覆盖和衬里；结缔组织负责支撑和连接，包括骨和血液；肌组织负责收缩；神经组织负责通信。组织包括细胞及不同程度的细胞外成分。</p><div class=\"teacher\">先自己算L=3 μm时的比值，再解释为什么体积增加意味着更多需求，而表面增加意味着更多交换机会。</div>", "englishHtml": "<h2>A cell is a living unit, not just a bag of chemicals</h2><p>Cells are the basic units of organisms and maintain organised internal conditions. Existing cells give rise to new cells. Stem cells can generate specialised cell types, but the lecture’s wording should not be read as saying that every living cell comes directly from a stem cell. Hooke named “cells” after observing cork compartments.</p><p>Typical prokaryotic sizes in the slides are 1–10 μm; typical eukaryotic sizes are 10–100 μm. These are approximate ranges, not universal limits. 1 μm = 0.001 mm; 1 nm = 0.001 μm.</p><p>Shapes include squamous (flat), cuboidal (cube-like), columnar (tall), polygonal, stellate (star-like), spheroid, discoid, spindle-shaped and fibrous. Flattening shortens some transport distances; long processes can support communication. Shape gives clues to function but does not by itself prove a cell’s identity.</p><h3>Why does getting bigger make exchange harder?</h3><p>For a cube of side L, area = 6L² and volume = L³, so area/volume = 6/L. At L = 1 μm the ratio is 6 μm⁻¹; at L = 2 μm it is 3 μm⁻¹. Doubling size gives four times the exchange area but eight times the volume. Smaller size often favours exchange and shorter diffusion distances.</p><p>Four basic tissue classes organise specialised cells: epithelial (covering and lining), connective (support and connection, including bone and blood), muscle (contraction), and nervous (communication). Tissues include cells and, to differing extents, extracellular material.</p><div class=\"teacher\">Before checking the quiz, calculate the ratio for L = 3 μm. Then explain why extra volume is a demand, while extra surface is an exchange opportunity.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "cell-size-1", "text": "立方体边长翻倍，表面积体积比如何变化？", "options": ["减半", "不变", "翻倍"], "answer": 0, "explain": "面积/体积=6/L，L翻倍则比值减半；面积增至4倍，体积增至8倍。"}, {"id": "cell-size-2", "text": "骨和血液属于哪类基本组织？", "options": ["神经", "上皮", "结缔"], "answer": 2, "explain": "骨和血液虽然外观不同，但都是特化的结缔组织。"}]}, {"id": "microscopy", "week": 2, "title": "怎样研究细胞：分辨率与分离", "en": "Microscopy & Cell Fractionation", "time": "18–25 分钟", "pages": "10–16", "goals": ["区分放大倍数与分辨率", "解释细胞分级分离步骤"], "englishGoals": ["Distinguish magnification from resolution", "Explain fractionation steps"], "html": "<h2>图像更大不一定更清楚</h2><p>放大倍数表示图像比物体大多少；分辨率表示两个点相距多近时仍可分辨。把模糊图像继续放大，只增加尺寸，不能恢复丢失细节。能够分辨的最小距离越小，分辨率越好。</p><p>讲义给光学显微镜的近似值为200 nm分辨率、1,000倍放大；苏木精—伊红（H&E）等染色可改善对比度。电子显微镜显示更精细的超微结构；讲义所列0.5 nm与高达千万倍是示例能力，不代表每张图像。重金属制样可提高电子对比度。</p><p>显微镜主要展示结构。生物化学可研究功能：匀浆先破开细胞，分级分离再分开成分，常通过离心；随后检测富集组分中的分子或酶活性。更高转速或更长时间可沉降前面离心后仍留在上清中的较小成分。</p><div class=\"teacher\">研究线粒体酶时，可以富集线粒体组分并测量活性。看到一个细胞器与测出一种功能回答不同的问题；组分污染会限制功能归属的把握。</div>", "englishHtml": "<h2>A bigger image is not automatically a clearer image</h2><p>Magnification tells you how much larger the image is than the object. Resolution tells you how close two points can be while still being distinguished. Enlarging an already blurred image increases magnification without recovering missing detail. A smaller resolvable distance means better resolution.</p><p>The lecture gives approximately 200 nm resolution and 1,000× magnification for light microscopy. Stains such as haematoxylin and eosin (H&E) improve contrast. Electron microscopy reveals finer ultrastructure; the quoted 0.5 nm and up to 10,000,000× are illustrative instrument capabilities, not a promise for every image. Heavy-metal preparation improves electron contrast.</p><p>Microscopy primarily shows structure. Biochemistry can investigate function: homogenisation breaks cells open; fractionation separates components, often by centrifugation; enriched fractions are examined for molecules or enzyme activity. Faster or longer centrifugation can sediment smaller components remaining after earlier spins.</p><div class=\"teacher\">To investigate a mitochondrial enzyme, you could enrich a mitochondrial fraction and measure activity. A visible organelle and a functional measurement answer different questions; contamination limits how confidently you assign a function.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "microscopy-1", "text": "图像被放大，但两个邻近结构仍分不开，改善了什么？", "options": ["标本真实尺寸", "只有放大倍数", "分辨率必然提高"], "answer": 1, "explain": "仅放大不能改善分辨率或恢复未分辨的信息。"}, {"id": "microscopy-2", "text": "分级分离前匀浆的目的是什么？", "options": ["破开细胞释放组分", "制造新细胞核", "翻译DNA"], "answer": 0, "explain": "先释放细胞内组分，才能分离并检测它们。"}]}, {"id": "cell-types", "week": 2, "title": "原核与真核：共同点和区别", "en": "Prokaryotic & Eukaryotic Cells", "time": "18–25 分钟", "pages": "17–22", "goals": ["识别共有的细胞结构", "区分细胞核与拟核"], "englishGoals": ["Identify shared cellular machinery", "Distinguish nucleus from nucleoid"], "html": "<h2>没有细胞核不等于没有DNA</h2><p>典型原核或真核细胞都有细胞膜、细胞溶胶、遗传物质和核糖体。讲义展示细菌域、古菌域和真核域；细菌和古菌具有原核组织形式，动物、植物和真菌属于真核生物。</p><p>原核细胞没有膜包围的细胞核，也没有真核细胞典型的膜性细胞器。DNA位于<strong>拟核 nucleoid</strong>，这一位置没有核膜。原核细胞仍有核糖体，仍能合成蛋白，多为单细胞。</p><p>典型真核细胞用细胞核、内质网、高尔基体等细胞器分隔功能。“真核”描述细胞组织形式，不代表每个特化成年细胞都保留全部细胞器；成熟哺乳动物红细胞是重要例外。</p><p>细胞溶胶是液体成分；细胞质通常包括细胞核外的细胞溶胶和结构。不要把细胞溶胶、细胞质和细胞核混用。</p><div class=\"callout\">选择题问原核细胞缺少什么时，应区分膜包围的细胞核与DNA、细胞膜或核糖体。</div>", "englishHtml": "<h2>No nucleus does not mean no DNA</h2><p>A typical prokaryotic or eukaryotic cell has a plasma membrane, cytosol, genetic material and ribosomes. The three domains shown are Bacteria, Archaea and Eukaryota. Bacteria and archaea have prokaryotic organisation; animals, plants and fungi are eukaryotic.</p><p>Prokaryotes lack a membrane-enclosed nucleus and the membrane-bound organelles typical of eukaryotes. Their DNA occupies a <strong>nucleoid</strong>, an area without a nuclear envelope. They still have ribosomes and can synthesise proteins. Most are single-celled.</p><p>Typical eukaryotic cells compartmentalise functions in a nucleus, endoplasmic reticulum, Golgi apparatus and other organelles. “Eukaryotic” describes a cellular organisation, not an assertion that every specialised adult cell retains all organelles; mature mammalian red blood cells are an important exception.</p><p>Cytosol is the fluid component. Cytoplasm generally includes cytosol and structures outside the nucleus. Do not use cytosol, cytoplasm and nucleus as interchangeable names.</p><div class=\"callout\">When an MCQ asks what prokaryotes lack, choose a membrane-enclosed nucleus rather than DNA, a plasma membrane or ribosomes.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "cell-types-1", "text": "典型细菌细胞缺少哪种结构？", "options": ["核糖体", "膜包围的细胞核", "遗传物质"], "answer": 1, "explain": "细菌有DNA和核糖体，但没有核膜包围其DNA。"}, {"id": "cell-types-2", "text": "哪一组属于原核组织形式的域？", "options": ["动物和植物", "真菌和动物", "细菌和古菌"], "answer": 2, "explain": "细菌域和古菌域具有原核细胞组织形式。"}]}, {"id": "cell-membrane", "week": 2, "title": "细胞膜：运输、信号与识别", "en": "Plasma Membrane Functions", "time": "18–25 分钟", "pages": "25–26", "goals": ["将双层结构与选择性交换联系起来", "识别膜蛋白的作用"], "englishGoals": ["Connect the bilayer with selective exchange", "Recognise membrane-protein roles"], "html": "<h2>细胞膜既是边界，也是交流界面</h2><p>细胞膜是含蛋白、胆固醇及相关糖类的磷脂双层。它调节物质和信号进出，帮助维持细胞体积与细胞质组成。选择性通透意味着不同物质不能以同样方式通过。</p><p>氧等小非极性分子可较容易穿过脂双层；离子一般需要运输蛋白。通道提供路径，门控通道响应信号开闭。水可跨膜，并常通过水通道蛋白高效运输。这些运输例子用于补充讲义的结构概念。</p><p>讲义列出六类膜蛋白功能：受体结合化学信号，酶催化反应，通道允许运输，门控通道调节通过，身份标记帮助识别，黏附分子连接细胞。受体可以检测信号，而不必将信号分子运过膜。</p><div class=\"teacher\">分清“分子进入细胞了吗”和“细胞收到信号了吗”。信号分子仍在外面时，结合表面受体也可改变内部信号。</div>", "englishHtml": "<h2>A membrane is both a boundary and an interface</h2><p>The plasma membrane is a phospholipid bilayer containing proteins, cholesterol and associated carbohydrates. It helps regulate substances and signals entering and leaving, supporting cell volume and cytoplasmic composition. Selective permeability means substances do not all cross in the same way.</p><p>Small non-polar molecules such as oxygen can cross the lipid bilayer relatively readily. Ions generally require transport proteins. Channels provide pathways; gated channels open or close in response to signals. Water can cross membranes, often efficiently through aquaporin channels. These transport examples extend the structural idea in the slides.</p><p>The lecture identifies six membrane-protein roles: receptors bind chemical messengers; enzymes catalyse reactions; channels allow transport; gated channels regulate passage; identity markers help recognition; adhesion molecules bind cells together. A receptor can detect a signal without transporting the signal molecule across the membrane.</p><div class=\"teacher\">Separate two questions: “Did a molecule enter?” and “Did the cell receive a message?” Binding a surface receptor may change internal signalling while the messenger remains outside.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "cell-membrane-1", "text": "激素结合表面蛋白并触发内部反应，该蛋白最可能在做什么？", "options": ["DNA复制", "构建细胞壁", "受体信号传递"], "answer": 2, "explain": "受体检测细胞外信号，可在不输入信号分子的情况下触发反应。"}, {"id": "cell-membrane-2", "text": "一个通道接收信号后从关闭变开放，描述哪种功能？", "options": ["核糖体", "门控通道", "核苷酸"], "answer": 1, "explain": "门控通道通过开闭状态调节通过。"}]}, {"id": "nucleus-dna", "week": 2, "title": "细胞核与DNA：配对和包装", "en": "Nucleus & DNA Structure", "time": "18–25 分钟", "pages": "27–31", "goals": ["区分细胞核与核仁", "在明确方向下进行DNA配对"], "englishGoals": ["Distinguish nucleus and nucleolus", "Pair DNA bases with direction stated"], "html": "<h2>细胞核组织DNA并调节相关交通</h2><p>核膜是带核孔的双层膜，核孔调节分子交通。染色质是DNA与组蛋白等蛋白的复合物。核仁是生产核糖体RNA并组装核糖体亚基的特化区域，不等于整个细胞核，也不是原核拟核。</p><p>DNA核苷酸含脱氧核糖、磷酸和一个碱基。腺嘌呤A与鸟嘌呤G为双环嘌呤；胞嘧啶C与胸腺嘧啶T为单环嘧啶。RNA使用核糖，并以尿嘧啶U替代T。</p><p>共价键连接糖—磷酸骨架，链间碱基通过氢键配对：A配T，G配C。两条链反向平行。对5′-ATGC-3′，按位置对齐的互补链为3′-TACG-5′；若将互补链自身按5′到3′书写，则为5′-GCAT-3′。</p><div class=\"teacher\">配对前先看方向标记。“逐个碱基替换”与“按5′到3′写反向互补序列”不是同一任务。老师的简短选择题省略方向，这里的练习会明确说明。</div><p>DNA通过包括与组蛋白结合在内的有序包装进入小细胞核。常染色质相对疏松，异染色质更凝缩；包装影响可及性，而不是删除遗传信息。</p>", "englishHtml": "<h2>The nucleus organises and regulates access to DNA</h2><p>The nuclear envelope is a double membrane with nuclear pores that regulate molecular traffic. Chromatin is DNA associated with proteins, including histones. The nucleolus is a specialised region where ribosomal RNA is produced and ribosomal subunits are assembled; it is not the same as the whole nucleus or a prokaryotic nucleoid.</p><p>A DNA nucleotide contains deoxyribose, phosphate and one base. Adenine (A) and guanine (G) are two-ring purines; cytosine (C) and thymine (T) are one-ring pyrimidines. RNA uses ribose and uracil (U) instead of thymine.</p><p>Covalent bonds hold the sugar–phosphate backbone together. Hydrogen bonds pair bases between strands: A with T, G with C. The strands are antiparallel. For 5′-ATGC-3′, the aligned complement is 3′-TACG-5′; written in its own 5′→3′ direction it is 5′-GCAT-3′.</p><div class=\"teacher\">Read the direction labels before complementing a sequence. “Replace each base” and “write the reverse complement in 5′→3′” are not identical tasks. The lecture’s short MCQs omit direction; our exercises state it explicitly.</div><p>DNA fits into a small nucleus through organised packaging, including association with histones. Euchromatin is relatively less condensed and heterochromatin more condensed; packing affects accessibility rather than deleting the genetic information.</p>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "nucleus-dna-1", "text": "典型真核细胞在哪里组装核糖体亚基？", "options": ["细胞膜", "核仁", "溶酶体"], "answer": 1, "explain": "核仁生产rRNA并组装核糖体亚基，亚基随后离开细胞核。"}, {"id": "nucleus-dna-2", "text": "5′-AGTC-3′按位置对齐的互补链是哪条？", "options": ["3′-TCAG-5′", "3′-UCAG-5′", "3′-AGTC-5′"], "answer": 0, "explain": "DNA中A配T、G配C，对齐的链方向相反；U用于RNA而不是通常的DNA。"}]}, {"id": "er-golgi", "week": 2, "title": "内质网与高尔基体：蛋白的路线", "en": "ER & Golgi Trafficking", "time": "18–25 分钟", "pages": "32–34", "goals": ["区分粗面与滑面内质网", "追踪分泌蛋白路径"], "englishGoals": ["Distinguish rough and smooth ER", "Trace a secreted protein"], "html": "<h2>把细胞器看成协作空间，不是孤立名称</h2><p>内质网是囊和管构成的膜网络，内部空间称为腔。内质网膜与外核膜连续，但这不意味着内质网腔就是核内液。</p><p>粗面内质网表面有核糖体，支持许多分泌蛋白和膜蛋白的合成、折叠及早期加工。翻译由核糖体执行，内质网提供相关区室。游离核糖体制造许多留在细胞溶胶的蛋白，因此并非所有蛋白都经过粗面内质网。</p><p>滑面内质网没有附着的核糖体，参与脂质/类固醇合成、解毒和钙储存，具体作用随细胞类型变化。肌细胞特化的滑面内质网重要地储存Ca²⁺；肝细胞滑面内质网参与解毒和部分葡萄糖代谢。</p><p>高尔基体接收内质网的货物，进行修饰、分选并包装进囊泡。许多分泌蛋白的路径为：内质网附着核糖体→粗面内质网腔→运输囊泡→高尔基体→分泌囊泡→细胞膜/胞吐。</p><div class=\"teacher\">工厂类比：核糖体建立链，内质网支持早期加工，高尔基体分选投递，囊泡运输。问每一步增加了什么作用，不要都叫“合成蛋白”。</div>", "englishHtml": "<h2>Think of connected workspaces, not isolated labels</h2><p>The endoplasmic reticulum (ER) is a membrane network of sacs and tubules whose interior is called the lumen. The ER membrane is continuous with the outer nuclear membrane; this does not mean the ER lumen is simply the nucleoplasm.</p><p>Rough ER has attached ribosomes and supports synthesis, folding and early processing of many secreted and membrane proteins. Ribosomes carry out translation; the ER is the associated compartment. Free ribosomes make many proteins that remain in the cytosol, so not every protein passes through rough ER.</p><p>Smooth ER lacks attached ribosomes and contributes to lipid/steroid synthesis, detoxification and calcium storage, with roles varying by cell type. Specialised smooth ER in muscle is important for Ca²⁺ storage; liver smooth ER participates in detoxification and aspects of glucose metabolism.</p><p>The Golgi receives cargo from ER, modifies it, sorts it and packages it into vesicles. For many secreted proteins: ER-bound ribosome → rough ER lumen → transport vesicle → Golgi → secretory vesicle → plasma membrane/exocytosis.</p><div class=\"teacher\">A factory analogy: ribosomes build chains, ER supports early processing, Golgi sorts deliveries, and vesicles transport cargo. Ask what each step adds rather than calling all of them “protein synthesis”.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "er-golgi-1", "text": "哪条路线符合典型分泌蛋白？", "options": ["粗面内质网→高尔基体→分泌囊泡", "高尔基体→DNA→仅溶酶体", "核仁→线粒体→膜"], "answer": 0, "explain": "分泌货物经过粗面内质网和高尔基体加工，再由囊泡投递。"}, {"id": "er-golgi-2", "text": "肌细胞在特化膜网络中储存Ca²⁺，涉及哪个结构？", "options": ["核仁", "染色质", "滑面内质网"], "answer": 2, "explain": "特化的滑面内质网即肌浆网，为肌功能储存钙。"}]}, {"id": "protein-synthesis", "week": 2, "title": "从DNA到蛋白：转录与翻译", "en": "Transcription & Translation", "time": "18–25 分钟", "pages": "35；29–30复习", "goals": ["区分转录与翻译", "从明确的DNA模板推导RNA"], "englishGoals": ["Separate transcription and translation", "Use a stated DNA template to derive RNA"], "html": "<h2>信息路线是DNA→RNA→蛋白</h2><p>在典型真核细胞中，转录在细胞核内使用DNA模板制造RNA。RNA聚合酶读取3′到5′的DNA模板，并按5′到3′合成RNA。成熟mRNA经核孔输出。DNA并不是物质上变成RNA，而是提供序列信息。</p><p>若明确模板为3′-TACGAA-5′，RNA为5′-AUGCUU-3′。RNA中的U与模板A配对，模板T对应RNA的A。若给出的是编码链，mRNA的5′到3′序列与它相同，只需以U替T。答题前先识别模板链或编码链。</p><p>翻译发生在核糖体。核糖体读取mRNA三碱基密码子，tRNA用反密码子配对并递送氨基酸，核糖体将氨基酸连接成多肽。AUG通常启动翻译并编码甲硫氨酸；终止密码子使翻译结束。</p><div class=\"teacher\">上面的AUG | CUU含两个密码子，不是六个氨基酸。密码子是信息单位，核苷酸是分子组成单位；需要同时明确方向和链的身份。</div><div class=\"callout\">复制拷贝DNA；转录以DNA为模板制造RNA；翻译利用mRNA制造多肽；新的蛋白随后还可能折叠、组装或继续加工。</div>", "englishHtml": "<h2>The information route is DNA → RNA → protein</h2><p>In a typical eukaryotic cell, transcription uses a DNA template to make RNA in the nucleus. RNA polymerase builds RNA in the 5′→3′ direction while reading the DNA template 3′→5′. Mature mRNA is exported through nuclear pores. DNA is not converted physically into RNA; its sequence provides information.</p><p>For a stated template 3′-TACGAA-5′, the RNA is 5′-AUGCUU-3′. A pairs with U in RNA; T in the DNA template directs A in RNA. If the given strand is the coding strand instead, mRNA matches its 5′→3′ sequence except that U replaces T. Identify template versus coding before answering.</p><p>Translation occurs on ribosomes. The ribosome reads mRNA codons (three bases); tRNAs pair anticodons with codons and deliver amino acids. Ribosomes join amino acids into a polypeptide. AUG commonly initiates translation and codes for methionine; stop codons end it.</p><div class=\"teacher\">In the example, AUG | CUU contains two codons, not six amino acids. A codon is an information unit; a nucleotide is a molecular building unit. Sequence direction and strand identity must both be clear.</div><div class=\"callout\">Replication copies DNA; transcription makes RNA from a DNA template; translation builds a polypeptide using mRNA. A new protein may then fold, assemble or undergo further processing.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "protein-synthesis-1", "text": "模板3′-TACGAA-5′转录出的RNA是哪条？", "options": ["5′-ATGCTT-3′", "5′-TACGAA-3′", "5′-AUGCUU-3′"], "answer": 2, "explain": "与明确的模板互补配对，RNA用U不用T，产物方向与模板相反。"}, {"id": "protein-synthesis-2", "text": "翻译时哪个分子将氨基酸送到核糖体？", "options": ["胆固醇", "tRNA", "DNA聚合酶"], "answer": 1, "explain": "转运RNA携带氨基酸，并以反密码子识别mRNA密码子。"}]}, {"id": "mitochondria-lysosomes", "week": 2, "title": "线粒体、溶酶体与过氧化物酶体", "en": "Energy Conversion & Recycling", "time": "18–25 分钟", "pages": "36–37；22图示补充", "goals": ["解释ATP产生的位置", "区分能量转化与消化回收"], "englishGoals": ["Explain where ATP generation occurs", "Distinguish energy conversion from digestion"], "html": "<h2>细胞需要可用能量，也需要受控回收</h2><p>线粒体有外膜和内膜，内膜折成嵴以增加膜面积。核心作用是能量转化：食物分子的能量支持ATP生成。它们转换能量，而不是凭空创造能量。</p><p>为澄清讲义的简化表述：糖酵解发生在细胞溶胶，柠檬酸/克雷布斯循环主要在线粒体基质，电子传递链与ATP合酶位于内膜。氧化磷酸化将电子传递及质子梯度与ATP合成耦合。</p><p>溶酶体在酸性内部含消化酶，降解送入的物质，包括老化成分和吞入的货物，使回收在特定区室内受控进行。“垃圾桶”只是记忆类比，不是完整功能描述。</p><p>细胞总图标出的过氧化物酶体含氧化反应相关酶，参与部分脂质代谢，过氧化氢酶帮助分解过氧化氢。它们与溶酶体不同，尽管两者都能处理潜在有害物质。</p><div class=\"teacher\">将结构与机制匹配：嵴提供能量转化所需膜面积，溶酶体酸性区室支持消化。再解释为什么一个细胞可以有核糖体却没有线粒体。</div>", "englishHtml": "<h2>Cells need usable energy and controlled recycling</h2><p>Mitochondria have outer and inner membranes. The inner membrane folds into cristae, increasing membrane area. Their central role is energy conversion: energy from food molecules supports ATP generation. They convert energy rather than create it from nothing.</p><p>For clarity beyond the lecture’s simplified labels: glycolysis occurs in the cytosol, much of the citric acid/Krebs cycle in the mitochondrial matrix, and the electron transport chain and ATP synthase in the inner membrane. Oxidative phosphorylation couples electron transfer and a proton gradient to ATP synthesis.</p><p>Lysosomes contain digestive enzymes in an acidic interior. They degrade delivered material, including worn components and engulfed cargo, so recycling is regulated within a compartment. “Trashcan” is a memory aid, not a complete description.</p><p>Peroxisomes, labelled in the cell overview, contain enzymes involved in oxidative reactions, including some lipid metabolism. Catalase helps break down hydrogen peroxide. They are distinct from lysosomes even though both process potentially damaging material.</p><div class=\"teacher\">Match structure with mechanism: cristae provide membrane area for energy conversion; an acidic lysosomal compartment supports digestion. Then explain why a cell can have ribosomes yet no mitochondria.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "mitochondria-lysosomes-1", "text": "线粒体电子传递链位于哪里？", "options": ["该细胞器的细胞膜", "内膜", "核仁"], "answer": 1, "explain": "线粒体内膜承载呼吸链成分，折叠增加可用膜面积。"}, {"id": "mitochondria-lysosomes-2", "text": "酸性细胞内消化最直接对应哪个区室？", "options": ["溶酶体", "仅高尔基体", "核孔"], "answer": 0, "explain": "溶酶体含在酸性条件下工作的消化酶，用于受控分解与回收。"}]}, {"id": "cytoskeleton", "week": 2, "title": "细胞骨架与整张细胞地图", "en": "Cytoskeleton & Cell Integration", "time": "18–25 分钟", "pages": "38；22复习", "goals": ["区分三类骨架成分", "将细胞器整合进功能解释"], "englishGoals": ["Distinguish three cytoskeletal components", "Integrate organelles in a functional explanation"], "html": "<h2>细胞骨架既支撑，又组织和运动</h2><p>微丝以肌动蛋白为基础，参与细胞运动、肌肉收缩和形状变化；中间丝包括上皮细胞中的角蛋白，抵抗机械应力并支持细胞连接；微管由微管蛋白形成中空结构，参与细胞内运输、纤毛/鞭毛及分裂时染色体运动。</p><p>总图中的中心粒与中心体和动物细胞微管组织有关。运动蛋白带囊泡沿微管移动，不等于微管在合成囊泡里的蛋白货物。支撑、运输和合成是不同作用。</p><h3>将一项细胞任务串起来</h3><p>释放蛋白信号时：核DNA提供信息→mRNA携带转录信息→核糖体制造链→粗面内质网支持加工→高尔基体分选→囊泡运动并与细胞膜融合。线粒体可提供细胞工作所需ATP，骨架支持运输，溶酶体回收损坏材料。</p><div class=\"teacher\">不看讲解，口头教一遍路线。如果运输受阻，蛋白合成可能仍在进行，但投递可能失败。好的解释会区分出问题的步骤与其他步骤。</div>", "englishHtml": "<h2>The cytoskeleton supports organisation and movement</h2><p>Microfilaments are actin-based and contribute to cell movement, muscle contraction and changes in cell shape. Intermediate filaments, including keratin in epithelial cells, resist mechanical stress and support cellular connections. Microtubules are tubulin-based hollow structures involved in intracellular transport, cilia/flagella and chromosome movement during division.</p><p>Centrioles and centrosomes, shown in the overview, are associated with microtubule organisation in animal cells. A motor protein moving a vesicle along a microtubule is not the microtubule synthesising that vesicle’s protein cargo. Structure, transport and synthesis are different roles.</p><h3>Put a whole cellular task together</h3><p>To release a protein signal: nuclear DNA provides information → mRNA carries a transcript → ribosomes build a chain → rough ER supports processing → Golgi sorts cargo → vesicles move and fuse with the membrane. Mitochondria can supply ATP for cellular work; cytoskeleton supports transport; lysosomes recycle damaged material.</p><div class=\"teacher\">Teach this route aloud without looking. If a transport step is disrupted, protein synthesis might still occur but delivery may fail. A good explanation separates the failed step from all the other steps.</div>", "source": "https://keats.kcl.ac.uk/mod/resource/view.php?id=10061530", "questions": [{"id": "cytoskeleton-1", "text": "哪个成分主要由微管蛋白构成？", "options": ["微管", "肌动蛋白微丝", "角蛋白中间丝"], "answer": 0, "explain": "微管以微管蛋白为基础，微丝以肌动蛋白为基础，角蛋白是中间丝例子。"}, {"id": "cytoskeleton-2", "text": "细胞正常制造分泌蛋白，但不能投递囊泡，哪项解释合适？", "options": ["一定没有任何DNA", "核糖体必然变成溶酶体", "合成继续时运输仍可能失败"], "answer": 2, "explain": "合成与货物运输是不同步骤，一个步骤失败不能单独证明其他步骤全部失败。"}]}];
LESSONS.push(...WEEK_ADDITIONS);
Object.assign(EN_QUESTIONS,{"classification-1": ["Which is the genus in Homo sapiens?", ["sapiens alone", "Mammalia", "Homo"], "Homo is the genus; the two-word name Homo sapiens identifies the species."], "classification-2": ["Which feature best supports classification as a mammal?", ["A vertebral column alone", "A plasma membrane", "Mammary glands"], "Mammary glands characterise mammals. A vertebral column is shared with other vertebrates."], "variation-1": ["Someone differs from a reference body mass. What can you conclude from that alone?", ["Reference models cannot be used", "They necessarily have a disease", "The model and the person differ; disease is not established"], "A reference is a comparison model. A difference alone does not establish pathology."], "variation-2": ["Why state the reference model’s activity and temperature?", ["They specify assumptions for interpretation", "They must apply to everyone", "They identify the person’s genus"], "A model’s results depend on its assumptions; these conditions help interpret it."], "regions-1": ["Which region refers to the back of the knee?", ["Patellar", "Popliteal", "Carpal"], "Popliteal identifies the posterior knee; patellar identifies the front of the knee."], "regions-2": ["What is the middle region in the nine-region abdominal map?", ["Umbilical", "Hypogastric", "Epigastric"], "The umbilical region is in the middle row and central column."], "cavities-1": ["Which serous layer directly covers an organ?", ["Visceral", "Neither", "Parietal"], "Visceral layers cover organs; parietal layers line cavity walls."], "cavities-2": ["The kidneys lie behind the parietal peritoneum. How are they classified?", ["Within a pleural cavity", "Intraperitoneal", "Retroperitoneal"], "Retroperitoneal means posterior to the parietal peritoneum; abdominal location alone does not imply intraperitoneal status."], "systems-1": ["Which system most directly transports oxygenated blood to tissues?", ["Reproductive", "Cardiovascular", "Integumentary"], "The heart and vessels move blood; the respiratory system enables gas exchange but does not itself circulate blood through all tissues."], "systems-2": ["What best explains increased ventilation and heart rate during exercise?", ["Systems act completely independently", "Several systems cooperate to meet changing demands", "Only the skeleton changes"], "Respiratory and cardiovascular changes help meet muscular metabolic demands under regulatory control."], "molecule-detail-1": ["Splitting a glycosidic bond using water is called what?", ["Hydrolysis", "Dehydration synthesis", "Translation"], "Hydrolysis consumes water in bond cleavage; dehydration joining releases water."], "molecule-detail-2": ["Several folded polypeptide subunits assemble into a protein. Which level is described?", ["Secondary", "Quaternary", "Primary"], "Quaternary structure concerns multiple polypeptide subunits; tertiary structure concerns one chain’s overall fold."], "cell-size-1": ["If a cube’s side doubles, what happens to its surface-area-to-volume ratio?", ["It halves", "It stays unchanged", "It doubles"], "Area/volume = 6/L; doubling L halves the ratio. Area increases fourfold and volume eightfold."], "cell-size-2": ["Which basic tissue class includes bone and blood?", ["Nervous", "Epithelial", "Connective"], "Bone and blood are specialised connective tissues, even though they look very different."], "microscopy-1": ["An image is enlarged but two close structures remain merged. What has improved?", ["The specimen’s true size", "Magnification only", "Resolution necessarily"], "Enlargement alone does not improve resolution or recover unresolved information."], "microscopy-2": ["What is the purpose of homogenisation before fractionation?", ["To open cells and release components", "To create a new nucleus", "To translate DNA"], "Components must first be released from cells before they can be separated and examined."], "cell-types-1": ["Which structure is absent from a typical bacterial cell?", ["Ribosomes", "A membrane-enclosed nucleus", "Genetic material"], "Bacteria have DNA and ribosomes but lack a nuclear envelope surrounding their DNA."], "cell-types-2": ["Which pair contains prokaryotic domains?", ["Animals and plants", "Fungi and animals", "Bacteria and Archaea"], "Bacteria and Archaea are the two domains with prokaryotic cellular organisation."], "cell-membrane-1": ["A hormone binds a surface protein and triggers an internal response. What is the protein most likely doing?", ["DNA replication", "Building a cell wall", "Receptor signalling"], "Receptors detect extracellular signals and can initiate responses without importing the messenger."], "cell-membrane-2": ["A channel changes from closed to open after a signal. Which role is described?", ["A ribosome", "A gated channel", "A nucleotide"], "Gated channels regulate passage by changing their opening state."], "nucleus-dna-1": ["Where are ribosomal subunits assembled in a typical eukaryotic cell?", ["Plasma membrane", "Nucleolus", "Lysosome"], "The nucleolus produces rRNA and assembles ribosomal subunits, which then leave the nucleus."], "nucleus-dna-2": ["What is the aligned complement of 5′-AGTC-3′?", ["3′-TCAG-5′", "3′-UCAG-5′", "3′-AGTC-5′"], "DNA pairs A–T and G–C, and the aligned strand runs antiparallel. U is used in RNA, not ordinary DNA."], "er-golgi-1": ["Which route best matches a typical secreted protein?", ["Rough ER → Golgi → secretory vesicle", "Golgi → DNA → lysosome only", "Nucleolus → mitochondrion → membrane"], "Secretory cargo is processed through rough ER and Golgi before vesicular delivery."], "er-golgi-2": ["A muscle cell stores Ca²⁺ in a specialised membrane network. Which structure is involved?", ["Nucleolus", "Chromatin", "Smooth ER"], "Specialised smooth ER, the sarcoplasmic reticulum, stores calcium for muscle function."], "protein-synthesis-1": ["Which RNA is transcribed from template 3′-TACGAA-5′?", ["5′-ATGCTT-3′", "5′-TACGAA-3′", "5′-AUGCUU-3′"], "Use complementary pairing to the stated template and U instead of T in RNA; the product runs antiparallel."], "protein-synthesis-2": ["Which molecule carries amino acids to a ribosome during translation?", ["Cholesterol", "tRNA", "DNA polymerase"], "Transfer RNA carries amino acids and uses its anticodon to recognise an mRNA codon."], "mitochondria-lysosomes-1": ["Where is the electron transport chain in a mitochondrion?", ["Plasma membrane of the same organelle", "Inner membrane", "Nucleolus"], "The inner mitochondrial membrane houses respiratory-chain components; its folds increase available membrane area."], "mitochondria-lysosomes-2": ["Which compartment is most directly associated with acidic intracellular digestion?", ["Lysosome", "Golgi only", "Nuclear pore"], "Lysosomes contain acid-active digestive enzymes for controlled breakdown and recycling."], "cytoskeleton-1": ["Which component is mainly built from tubulin?", ["Microtubules", "Actin microfilaments", "Keratin intermediate filaments"], "Microtubules are tubulin-based; microfilaments are actin-based; keratin is an intermediate-filament example."], "cytoskeleton-2": ["A cell makes a secreted protein normally but cannot deliver its vesicles. Which interpretation fits?", ["All DNA must be absent", "Ribosomes necessarily become lysosomes", "Transport can fail despite continued synthesis"], "Synthesis and cargo transport are distinct steps; failure in one does not by itself prove failure in every other step."], "week-review-1": ["An organ lies behind the parietal peritoneum. What matters for its classification?", ["Its colour", "Whether it contains proteins", "Its relationship to the peritoneum"], "The stated position identifies a retroperitoneal relationship."], "week-review-2": ["A protein contains four polypeptide subunits. Which structure level involves their association?", ["Secondary only", "Quaternary", "Primary only"], "Association of different polypeptide subunits describes quaternary structure."], "week-review-3": ["A finger is farther from the upper limb’s attachment than the wrist. Which term applies?", ["Distal to the wrist", "Proximal to the wrist", "Superior by definition"], "Distal compares distance from attachment or origin."], "week-review-4": ["Adding water splits a disaccharide into monosaccharides. What process is this?", ["Condensation", "Translation", "Hydrolysis"], "Hydrolysis uses water in bond cleavage."], "week-review-5": ["The lungs exchange gases while blood carries them to muscle. What does this illustrate?", ["No need for homeostasis", "Cooperation between systems", "A single isolated organ doing every task"], "Respiratory and cardiovascular roles complement each other."], "week-review-6": ["A diagram shows a patient facing you. Their right upper abdomen appears on which side of the image?", ["Your left", "Your right", "Always the bottom"], "Anatomical left and right refer to the subject, so facing each other reverses the viewer’s sides."], "week-review-7": ["A cell doubles each dimension. What is its new surface-area-to-volume ratio relative to the old one?", ["Twice", "Eight times", "One half"], "Area scales with length squared and volume cubed, so the ratio scales inversely with length."], "week-review-8": ["A bacterial cell synthesises proteins without a nucleus. Which structure enables translation?", ["A Golgi apparatus", "Ribosomes", "A nuclear envelope"], "Prokaryotes possess ribosomes, even though they lack a membrane-enclosed nucleus."], "week-review-9": ["The coding DNA strand is 5′-ATGCCA-3′. Which mRNA sequence matches it?", ["5′-AUGCCA-3′", "5′-UACGGU-3′", "5′-ATGCCA-3′"], "mRNA matches the coding strand in the same direction with U replacing T; complement the template, not the coding strand."], "week-review-10": ["A protein is translated, but its Golgi sorting signal is disrupted. What might fail?", ["The existence of every ribosome", "All ATP generation necessarily", "Delivery to the appropriate destination"], "Golgi sorting controls destinations; a sorting defect does not imply global loss of synthesis."], "week-review-11": ["Which association is correct?", ["Keratin—mRNA", "Actin—microfilaments", "Tubulin—chromatin"], "Actin forms microfilaments; tubulin forms microtubules; keratin is an intermediate filament."], "week-review-12": ["An acidic compartment digests worn cellular components. Which structure best fits?", ["Lysosome", "Nucleolus", "Nuclear pore"], "Acidic intracellular digestion and recycling are characteristic lysosomal roles."]});
window.WEEK_REVIEW=[{"id": "week-review-1", "text": "器官位于壁层腹膜之后，分类时最重要的信息是什么？", "options": ["颜色", "是否含蛋白", "它与腹膜的位置关系"], "answer": 2, "explain": "所给位置说明腹膜后关系。", "week": 1}, {"id": "week-review-2", "text": "蛋白有四个多肽亚基，它们的组合对应哪级结构？", "options": ["仅二级", "四级", "仅一级"], "answer": 1, "explain": "多个多肽亚基的组合描述四级结构。", "week": 1}, {"id": "week-review-3", "text": "手指比腕更远离上肢连接处，应用哪个词？", "options": ["位于腕的远端", "位于腕的近端", "按定义为上方"], "answer": 0, "explain": "远端比较与连接处或起点的距离。", "week": 1}, {"id": "week-review-4", "text": "利用水将双糖拆为单糖，是什么过程？", "options": ["缩合", "翻译", "水解"], "answer": 2, "explain": "水解在断键时利用水。", "week": 1}, {"id": "week-review-5", "text": "肺交换气体，血液再将气体送到肌肉，说明什么？", "options": ["不需要稳态", "系统协作", "单个孤立器官完成全部任务"], "answer": 1, "explain": "呼吸与心血管系统的作用互相补充。", "week": 1}, {"id": "week-review-6", "text": "图中人正面对你，其右上腹在图像哪侧？", "options": ["你的左侧", "你的右侧", "总在底部"], "answer": 0, "explain": "解剖左右指人体自身，面对面时与观察者左右相反。", "week": 1}, {"id": "week-review-7", "text": "细胞各线性尺寸翻倍，新表面积体积比相对原来是多少？", "options": ["两倍", "八倍", "一半"], "answer": 2, "explain": "面积随长度平方增长，体积随立方增长，因此比值与长度成反比。", "week": 2}, {"id": "week-review-8", "text": "细菌没有细胞核却能合成蛋白，什么结构执行翻译？", "options": ["高尔基体", "核糖体", "核膜"], "answer": 1, "explain": "原核细胞虽然没有膜包围的细胞核，仍有核糖体。", "week": 2}, {"id": "week-review-9", "text": "DNA编码链为5′-ATGCCA-3′，对应mRNA是哪条？", "options": ["5′-AUGCCA-3′", "5′-UACGGU-3′", "5′-ATGCCA-3′"], "answer": 0, "explain": "mRNA同方向匹配编码链，以U替T；需要互补的是模板链，不是编码链。", "week": 2}, {"id": "week-review-10", "text": "蛋白已被翻译，但高尔基体分选信号受损，可能哪步失败？", "options": ["全部核糖体的存在", "全部ATP生成必然失败", "送往正确目的地"], "answer": 2, "explain": "高尔基体分选决定目的地，分选缺陷不意味着全局合成消失。", "week": 2}, {"id": "week-review-11", "text": "哪项对应正确？", "options": ["角蛋白—mRNA", "肌动蛋白—微丝", "微管蛋白—染色质"], "answer": 1, "explain": "肌动蛋白构成微丝，微管蛋白构成微管，角蛋白属于中间丝。", "week": 2}, {"id": "week-review-12", "text": "酸性区室消化老化细胞成分，最符合哪个结构？", "options": ["溶酶体", "核仁", "核孔"], "answer": 0, "explain": "酸性细胞内消化与回收是溶酶体的典型作用。", "week": 2}];

LESSONS[0].html+='<h3>观察结构的几种方法</h3><p>检查包括视诊、触诊（palpation）、听诊（auscultation）和叩诊（percussion）。解剖、探查手术和影像是其他方法；影像包括X线、CT、超声、MRI及PET。不同方法提供不同类型的信息。</p>';
LESSONS[0].englishHtml+='<h3>Ways to investigate structure</h3><p>Inspection can include looking, palpation (touch), auscultation (listening) and percussion (tapping). Dissection, exploratory surgery and imaging offer other approaches. Imaging includes X-rays, CT, ultrasound, MRI and PET; different methods provide different types of information.</p>';
LESSONS.find(l=>l.id==='feedback').html+='<h3>把站起时的血压调节放进环路</h3><p>作为讲义问题的补充说明：站起可使血压短暂下降；颈动脉窦和主动脉弓压力感受器检测牵张变化，脑干心血管中枢整合信号，心脏与血管平滑肌等效应器调整心率、收缩及血管张力。反应帮助抵消血压下降，是负反馈。</p>';
LESSONS.find(l=>l.id==='feedback').englishHtml+='<h3>Place postural blood-pressure control in the loop</h3><p>To explain the lecture’s question: standing can briefly lower blood pressure. Baroreceptors in the carotid sinus and aortic arch detect changes in stretch; brainstem cardiovascular centres integrate signals; effectors including the heart and vascular smooth muscle adjust heart activity and vessel tone. The response counteracts the pressure fall: negative feedback.</p>';
